<script setup lang="ts">
import {ref,reactive,onMounted,computed,watch} from 'vue'
import {useRoute,useRouter,onBeforeRouteLeave} from 'vue-router'
import {api,message,notify,type Work} from '../api'
const route=useRoute(),router=useRouter(),works=ref<Work[]>([]),ready=ref(false),busy=ref(false),error=ref(''),candidate=ref(''),dirty=ref(false)
const form=reactive({title:'',description:'',kind:'连载',published:false,workIds:[] as number[]})
watch(form,()=>{if(ready.value)dirty.value=true},{deep:true,flush:'sync'})
const available=computed(()=>works.value.filter(w=>!form.workIds.includes(w.id)))
function title(id:number){return works.value.find(w=>w.id===id)?.title||'未命名稿件'}
function add(){const id=Number(candidate.value);if(id&&available.value.some(w=>w.id===id)){form.workIds.push(id);candidate.value=''}}
function move(i:number,delta:number){const ids=[...form.workIds];[ids[i],ids[i+delta]]=[ids[i+delta]!,ids[i]!];form.workIds=ids}
async function save(){busy.value=true;error.value='';try{const r=route.params.id?await api.put(`/member/collections/${route.params.id}`,form):await api.post('/member/collections',form);dirty.value=false;notify('合集已保存');router.push(`/collection/${r.data.id}`)}catch(e){error.value=message(e)}finally{busy.value=false}}
onMounted(async()=>{try{works.value=(await api.get('/member/works')).data;if(route.params.id){const c=(await api.get(`/public/collections/${route.params.id}`)).data;Object.assign(form,{title:c.title,description:c.description,kind:c.kind,published:c.published,workIds:c.works.map((w:Work)=>w.id)})}ready.value=true}catch(e){error.value=message(e)}})
onBeforeRouteLeave(()=>!dirty.value||confirm('合集修改尚未保存，确定离开？'))
</script>
<template><div class="container page-space collection-editor"><p class="eyebrow">我的合集</p><h1 class="page-title">{{route.params.id?'编辑合集':'新建合集'}}</h1><p v-if="error" role="alert" class="error-message">{{error}}</p><form v-if="ready" @submit.prevent="save"><div class="panel"><label>合集名称<input v-model="form.title" required maxlength="100"/></label><label>类型<select v-model="form.kind"><option>连载</option><option>诗集</option><option>选集</option></select></label><label>简介<textarea v-model="form.description" rows="3" maxlength="1000"></textarea></label><label class="checkbox-label"><input type="checkbox" v-model="form.published"/>公开合集</label><p class="quiet-note">未发布的篇目仅自己可见。可收录自己的稿件，最多 500 篇。</p></div><div class="section-heading"><h2>篇目顺序</h2></div><div class="collection-add"><select v-model="candidate" aria-label="选择稿件"><option value="">选择稿件</option><option v-for="w in available" :key="w.id" :value="w.id">{{w.title||'未命名稿件'}}{{w.status==='PUBLISHED'?'':'（未公开）'}}</option></select><button type="button" class="button secondary" :disabled="!candidate||form.workIds.length>=500" @click="add">添加</button></div><ol class="collection-contents editable"><li v-for="(id,i) in form.workIds" :key="id"><span>{{i+1}}</span><strong>{{title(id)}}</strong><div class="collection-order"><button type="button" :disabled="i===0" :aria-label="`上移第${i+1}篇`" @click="move(i,-1)">上移</button><button type="button" :disabled="i===form.workIds.length-1" :aria-label="`下移第${i+1}篇`" @click="move(i,1)">下移</button><button type="button" :aria-label="`移除第${i+1}篇`" @click="form.workIds.splice(i,1)">移除</button></div></li></ol><p v-if="!form.workIds.length" class="quiet-note">尚未添加篇目</p><button class="button" :disabled="busy">{{busy?'保存中…':'保存合集'}}</button></form></div></template>
